journals.script:
{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c03_started }
	OR = {
		AND = { c:OIR ?= this OR = { ywc_c03_case_ready_oir = yes var:ywc_c03_case_open ?= 1 } }
		AND = { OR = { c:MGL ?= this c:TIB ?= this c:SHU ?= this } var:ywc_c03_case_open ?= 1 }
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c03_started }
	OR = {
		AND = { c:OIR ?= this ywc_c03_case_ready_oir = yes }
		AND = { OR = { c:MGL ?= this c:TIB ?= this c:SHU ?= this } var:ywc_c03_case_open ?= 1 }
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c03_started } }
		set_variable = { name = ywc_c03_started value = 1 }
		set_variable = { name = ywc_c03_popup_epoch value = 0 }
		set_variable = { name = ywc_c03_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c03_popup_epoch } } set_variable = { name = ywc_c03_popup_epoch value = 0 } }
	if = { limit = { c:OIR ?= this NOT = { has_variable = ywc_c03_role } } set_variable = { name = ywc_c03_role value = 1 } }
	if = { limit = { c:MGL ?= this NOT = { has_variable = ywc_c03_role } } set_variable = { name = ywc_c03_role value = 2 } }
	if = { limit = { c:TIB ?= this NOT = { has_variable = ywc_c03_role } } set_variable = { name = ywc_c03_role value = 3 } }
	if = { limit = { c:SHU ?= this NOT = { has_variable = ywc_c03_role } } set_variable = { name = ywc_c03_role value = 4 } }
	if = { limit = { var:ywc_c03_role ?= 1 NOT = { has_variable = ywc_c03_stage } }
		set_variable = { name = ywc_c03_case_open value = 1 }
		set_variable = { name = ywc_c03_stage value = 1200 }
		set_variable = { name = ywc_c03_pending value = 1200 }
	}
	if = { limit = { OR = { var:ywc_c03_role ?= 2 var:ywc_c03_role ?= 3 var:ywc_c03_role ?= 4 } NOT = { has_variable = ywc_c03_stage } }
		set_variable = { name = ywc_c03_case_open value = 1 }
		set_variable = { name = ywc_c03_stage value = 1218 }
		set_variable = { name = ywc_c03_wait_age value = 0 }
	}
	if = { limit = { c:OIR ?= this c:MGL ?= { is_country_alive = yes has_variable = ywc_v03_initialized ywc_c03_contact_oir = yes NOT = { has_variable = ywc_c03_case_open } } }
		c:MGL = { set_variable = { name = ywc_c03_case_open value = 1 } set_variable = { name = ywc_c03_role value = 2 } set_variable = { name = ywc_c03_stage value = 1218 } set_variable = { name = ywc_c03_wait_age value = 0 } }
	}
	if = { limit = { c:OIR ?= this c:TIB ?= { is_country_alive = yes has_variable = ywc_v03_initialized ywc_c03_contact_oir = yes NOT = { has_variable = ywc_c03_case_open } } }
		c:TIB = { set_variable = { name = ywc_c03_case_open value = 1 } set_variable = { name = ywc_c03_role value = 3 } set_variable = { name = ywc_c03_stage value = 1218 } set_variable = { name = ywc_c03_wait_age value = 0 } }
	}
	if = { limit = { c:OIR ?= this c:SHU ?= { is_country_alive = yes has_variable = ywc_v03_initialized ywc_c03_contact_oir = yes NOT = { has_variable = ywc_c03_case_open } } }
		c:SHU = { set_variable = { name = ywc_c03_case_open value = 1 } set_variable = { name = ywc_c03_role value = 4 } set_variable = { name = ywc_c03_stage value = 1218 } set_variable = { name = ywc_c03_wait_age value = 0 } }
	}
}
on_monthly_pulse = {
	effect = {
		if = { limit = { var:ywc_c03_role ?= 1 var:ywc_c03_stage ?= 1213 }
			change_variable = { name = ywc_c03_wait_age add = 1 }
			if = { limit = { OR = { ywc_c03_responses_resolved = yes var:ywc_c03_wait_age >= 12 } } ywc_c03_init_after_responses = yes }
		}
		if = { limit = { OR = { var:ywc_c03_role ?= 2 var:ywc_c03_role ?= 3 var:ywc_c03_role ?= 4 } var:ywc_c03_stage ?= 1218 }
			change_variable = { name = ywc_c03_wait_age add = 1 }
			if = { limit = { OR = { ywc_c03_initiator_gone = yes var:ywc_c03_wait_age >= 36 } } ywc_c03_close_no_talks = yes }
		}
		if = { limit = { OR = { var:ywc_c03_role ?= 2 var:ywc_c03_role ?= 3 } OR = { var:ywc_c03_stage ?= 1202 var:ywc_c03_stage ?= 1203 } NOT = { ywc_c03_initiator_awaiting_transit = yes } }
			ywc_c03_close_no_talks = yes
		}
		if = { limit = { ywc_c03_oir_delivery_1200 = yes } trigger_event = { id = ywc_crisis.1200 } }
		if = { limit = { ywc_c03_oir_delivery_1201 = yes } trigger_event = { id = ywc_crisis.1201 } }
		if = { limit = { ywc_c03_mgl_delivery_1202 = yes } trigger_event = { id = ywc_crisis.1202 } }
		if = { limit = { ywc_c03_tib_delivery_1203 = yes } trigger_event = { id = ywc_crisis.1203 } }
	}
}
}

